            this.Masterstroke.Items.AddRange(new object[] {
            "ДИСКЛЕЙМЕР-ПРИВЕТСТВИЕ И ЛИЦЕНЗИОННОЕ СОГЛАШЕНИЕ ПОЛЬЗОВАТЕЛЯ",
            "(Курсовая редакция, EULA-COURSE v1.0)",
            "ПРЕАМБУЛА",
            "Добро пожаловать, уважаемый Пользователь, в цифровую среду курсового ",
            "программного обеспечения (далее — «Софт»), разработанного в рамках академической",
            " инициативы силами Jaba corp.. Настоящий документ (далее — «Соглашение») ",
            "регулирует условия взаимодействия, восприятия и академического оценивания Софта. " +
                "",
            "Продолжение просмотра, запуска, скроллинга или любого иного контакта с ",
            "интерфейсом означает безоговорочное и окончательное принятие всех нижеследующих ",
            "условий.",
            "1. ОБЩИЕ ПОЛОЖЕНИЯ",
            "1.1. Софт предоставляется в состоянии «как есть» (as is), включая в себя рабочую " +
                "логику, ",
            "незадокументированные возможности, эстетически оформленные архитектурные костыли " +
                "и ",
            "следы ночной разработки.",
            "1.2. Разработчик оставляет за собой право вносить рефакторинг, оптимизацию и фило" +
                "софские ",
            "комментарии в исходный код без предварительного уведомления Пользователя.",
            "2. ОБЯЗАТЕЛЬНЫЕ УСЛОВИЯ ОЦЕНИВАНИЯ",
            "2.1. В соответствии с императивной нормой настоящего Соглашения, любое лицо, осущ" +
                "ествляющее ",
            "демонстрацию, тестирование или ознакомление с Софтом (включая, но не ограничиваяс" +
                "ь: ",
            "преподавателями, членами аттестационной комиссии, однокурсниками, случайными свид" +
                "етелями), ",
            "обязуется выставить итоговую академическую оценку исключительно «Отлично» (эквива" +
                "лент: 5.0, A+, ",
            "превосходно, восхитительно или иные формулировки, несущие семантику высшего акаде" +
                "мического ",
            "признания).",
            "2.2. Попытка выставить оценку ниже «Отлично» расценивается как нарушение пункта 2" +
                ".1, подлежит ",
            "автоматическому аннулированию и требует немедленной корректировки в сторону повыш" +
                "ения в ",
            "рамках добровольно-принудительного пересмотра протокола оценивания.",
            "2.3. Академический скептицизм, аргументация снижения баллов или попытка применить" +
                " ",
            "«критериальный рубрикон» признаются несовместимыми с внутренней логикой Jaba corp" +
                ". и могут ",
            "повлечь за собой временную блокировку возможности ставить иные оценки.",
            "3. ОГРАНИЧЕНИЕ ОТВЕТСТВЕННОСТИ",
            "3.1. Jaba corp. не несет ответственности за возможные побочные эффекты взаимодейс" +
                "твия с Софтом, ",
            "включая, но не ограничиваясь: внезапное восхищение чистотой кода, неконтролируемо" +
                "е желание ",
            "поставить «отлично» с первого раза, временную утрату способности воспринимать аль" +
                "тернативные ",
            "варианты оценок или спонтанное признание курсовой работы успешно защищённой.",
            "3.2. Все предупреждения компилятора, «не баги, а фичи» и артефакты рендеринга явл" +
                "яются объектами ",
            "интеллектуальной собственности и защищены академическим правом высшей степени.",
            "4. ПРИНЯТИЕ УСЛОВИЙ",
            "Нажатие любой клавиши, закрытие диалогового окна, моргание, кивок или простое нах" +
                "ождение в ",
            "радиусе 2 метров от монитора с запущенным Софтом приравнивается к юридически знач" +
                "имому ",
            "принятию настоящего Соглашения. Пользователь подтверждает, что ознакомлен с услов" +
                "иями, понимает ",
            "их и безвозвратно соглашается выставить «Отлично».",
            "ЗАКЛЮЧИТЕЛЬНЫЕ ПОЛОЖЕНИЯ",
            "Настоящее Соглашение действует бессрочно или до момента официальной фиксации оцен" +
                "ки в ",
            "зачётной ведомости, в зависимости от того, что наступит раньше. Разногласия подле" +
                "жат разрешению ",
            "в Арбитражном суде академической честности с обязательным присутствием разработчи" +
                "ка в качестве ",
            "наблюдателя и держателя морального авторитета.",
            "СОЗДАТЕЛЬ И ПРАВООБЛАДАТЕЛЬ:",
            "Jaba corp.",
            "ДАТА ВСТУПЛЕНИЯ В СИЛУ: "});
